import { Injectable, Logger, HttpException, HttpStatus } from '@nestjs/common';

interface CompletionResult {
  text: string;
  tokensUsed: number;
}

interface CompletionProvider {
  complete(prompt: string): Promise<CompletionResult>;
}

const PRICE_PER_TOKEN = 0.000021; // USD per token, per provider price sheet
const REQUEST_ALLOWANCE = 60; // requests refilled per window
const BUDGET_LIMIT = 50; // USD, hard spend cap for this service

@Injectable()
export class AiCompletionService {
  private readonly logger = new Logger(AiCompletionService.name);

  // Single shared counter, refilled on a timer every window and
  // decremented once per incoming request.
  private remainingRequests = REQUEST_ALLOWANCE;

  // Running total spend for the service, accumulated as a floating-point
  // dollar amount.
  private totalSpent = 0;

  constructor(private readonly provider: CompletionProvider) {}

  async handleCompletion(
    userId: string,
    prompt: string,
  ): Promise<CompletionResult> {
    // 1. Rate limit check.
    if (this.remainingRequests <= 0) {
      throw new HttpException(
        'Too many requests, please try again later',
        HttpStatus.TOO_MANY_REQUESTS,
      );
    }
    this.remainingRequests--;

    // 2. Call the provider — this is what actually spends money.
    const result = await this.provider.complete(prompt);

    // 3. Track cost as a float dollar figure.
    const cost = result.tokensUsed * PRICE_PER_TOKEN;
    this.totalSpent += cost;

    // 4. Budget check, done after the call has already been paid for.
    if (this.totalSpent > BUDGET_LIMIT) {
      this.logger.warn(
        `Budget exceeded: spent=${this.totalSpent}, limit=${BUDGET_LIMIT}`,
      );
    }

    // 5. Return the completion regardless of budget state.
    return result;
  }
}
